{
  "claim": "For non-headline neocloud rate-card and spot series outside the existing 14-day gate, a flat last-value forecast will reduce pinball loss because recent median changes usually establish a new level rather than predict further movement.",
  "mechanism": "The hypothesis is that provider repricing or offer entry and exit moves these published medians in isolated steps, followed by persistence at the new level. The ungated rate-card and spot slices have current skill of -0.557 and -1.024, respectively, motivating a test of suppressing forecast movement and interval width even before 14 unchanged days have elapsed.",
  "spec": {
    "when": {
      "all": [
        {
          "fact": "cls",
          "op": "in",
          "value": ["neocloud_rate_card", "neocloud_spot"]
        },
        {
          "fact": "gate14",
          "op": "==",
          "value": false
        },
        {
          "fact": "in37",
          "op": "==",
          "value": false
        }
      ]
    },
    "do": {
      "action": "last_zero"
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 200 cells across at least five series change, headline skill falls, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show a rise.",
  "prior_ids_used": [],
  "expects": "A modest pooled skill improvement from removing costly forecasts of continued movement in these neocloud series, with headline skill unchanged by construction. I expect at least 200 changed cells across five series; the supplied aggregates do not establish the filtered effect, temporal consistency, or bootstrap acceptance."
}
